   public List<String> getList(ExpressionList el, String argu, List<String> expectedTypes, int offset) {
    List<String> exprTypes = new ArrayList<>();

    // First expression
    String expectedType = (expectedTypes != null && offset < expectedTypes.size()) ? expectedTypes.get(offset) : null;
    exprTypes.add(el.f0.accept(this, expectedType));

    // Remaining expressions
    int i = offset + 1;
    for (Node n : el.f1.nodes) {
        ExpressionRest er = (ExpressionRest) n;
        expectedType = (expectedTypes != null && i < expectedTypes.size()) ? expectedTypes.get(i) : null;
        exprTypes.add(er.f1.accept(this, expectedType));
        i++;
    }

    return exprTypes;
}

    
