   /**
    * f0 -> "("
    * f1 -> Identifier()
    * f2 -> ")"
    * f3 -> "->"
    * f4 -> Expression()
    */
   public String visit(LambdaExpression n, String argu) {
      String expectedType = argu;
      String paramType = null;
      String expectedRetType = null;
      if(expectedType!=null && expectedType.startsWith("Function<")){
         int commaIndex = expectedType.indexOf(',');
         paramType = expectedType.substring(9,commaIndex);
         expectedRetType = expectedType.substring(commaIndex+1,expectedType.length()-1);
      }
      String paramName = n.f1.f0.toString();
      String varTypetoAdd = "?";
      if(paramType!=null && !paramType.equals("?")){
         varTypetoAdd = paramType;
      }
      ST.addLocalVar(ST.currentClass,ST.currentMethod,paramName,varTypetoAdd);
      String retType = n.f4.accept(this, expectedRetType);
      if(retType == null){
            System.out.println("Type error\n");
            if(debug){
                System.err.println("Error: Lambda expr");
            }
            System.exit(0);
      }
      ST.removeLocalVar(ST.currentClass,ST.currentMethod,paramName);
      if(expectedRetType != null && !expectedRetType.equals("?") && !ST.possibleTypes(expectedRetType, retType)){
         System.out.println("Type error");
         if(debug){
             System.err.println("Error: Lambda return type");
         }
         System.exit(0);
      }

      String finalParamType = (paramType != null && !paramType.equals("?")) ? paramType : "?";
      return "Function<" + finalParamType + "," + retType + ">";
   }

