   /**
    * f0 -> PrimaryExpression()
    * f1 -> "."
    * f2 -> Identifier()
    * f3 -> "("
    * f4 -> ( ExpressionList() )?
    * f5 -> ")"
    */
   public String visit(MessageSend n, String argu) {
      String _ret=null;
      //n.f0.accept(this, argu);
      String peType = n.f0.accept(this,argu);
      n.f1.accept(this, argu);
      if("int".equals(peType) || "boolean".equals(peType)){
            System.out.println("Type Error\n");
            if(debug){
                System.err.println("Error: Message Send -> wrong object");
            }
            System.exit(0);
      }
      if("int[]".equals(peType)){
            System.out.println("Symbol not found\n");
            if(debug){
                System.err.println("Error: Message Send -> wrong object");
            }
            System.exit(0);
      }
      if(peType != null && peType.startsWith("Function<")){
         String methodName = n.f2.f0.toString();
         if(methodName.equals("apply")){
             int commaIndex = peType.indexOf(',');
             String paramType = peType.substring(9,commaIndex);
             String retType = peType.substring(commaIndex+1,peType.length()-1);
             if(n.f4.present()){
                List<String> expectedArgTypes = new ArrayList<>();
                expectedArgTypes.add(paramType);
                List<String> argTypes = getList((ExpressionList) n.f4.node, argu, expectedArgTypes, 0);

                if(argTypes.size() != 1){
                    System.out.println("Type error");
                    if(debug){
                        System.err.println("Error: apply expects 1 argument, but found " + argTypes.size() + ".");
                    }
                    System.exit(0);
                }
                String argType = argTypes.get(0);
                if(!paramType.equals("?") && !ST.possibleTypes(paramType,argType)){
                    System.out.println("Type error");
                    if(debug){
                        System.err.println("Error: argument of apply must be of type " + paramType + ", but found type " + argType + ".");
                    }
                    System.exit(0);
                }
                return retType;
             }
             else{
                System.out.println("Type error");
                if(debug){
                    System.err.println("Error: apply expects 1 argument, but found 0.");
                }
                System.exit(0);
             }
         }
      }

      if("int".equals(peType) || "boolean".equals(peType) || "int[]".equals(peType) || peType==null){
            System.out.println("Type Error\n");
            if(debug){
                System.err.println("Error: MessageSend -> wrong object");
            }
            System.exit(0);
      }
      String methodName = n.f2.f0.toString();
      MethodInfo minfo = ST.getMethod(peType,methodName);
      if(minfo == null){
            System.out.println("Symbol not found\n");
            if(debug){
                System.err.println("Error: MessageSend2");
            }
            System.exit(0);
      }
      String typicalReturnType = minfo.returnType;
      n.f3.accept(this, argu);
      List<String> argTypes = new ArrayList<>();
      if(n.f4.present()){
         List<String> expectedTypes = new ArrayList<>();
         for(String paramName : minfo.paramOrder){
            expectedTypes.add(minfo.parameters.get(paramName));
         }
         argTypes = getList((ExpressionList) n.f4.node, argu, expectedTypes, 0);
      }

      if(argTypes.size() != minfo.parameters.size()){
            System.out.println("Tyep error\n"); 
            if(debug){
                System.err.println("Error: In method " + ST.currentMethod + ", method " + methodName + " expects " + minfo.parameters.size() + " arguments, but found " + argTypes.size() + ".");
            }
            System.exit(0);
      }
      for(int i=0;i<argTypes.size();i++){
         String actual = argTypes.get(i);
         String paramName = minfo.paramOrder.get(i);
         String expected = minfo.parameters.get(paramName);
         if(!ST.possibleTypes(expected,actual)){
            System.out.println("Type error");
            if(debug){
                System.err.println("Error: In method " + ST.currentMethod + ", argument " + (i+1) + " of method " + methodName + " expects type " + expected + ", but found type " + actual + ".");
            }
            System.exit(0);
         }
      }
      n.f5.accept(this, argu);
      //System.out.println("He");
      return typicalReturnType;
   }

