   /**
    * f0 -> <IDENTIFIER>
    */
   public String visit(Identifier n, String argu) {
      String _ret=null;
      String varName = n.f0.toString();
      String varType = ST.getVariableType(ST.currentClass,ST.currentMethod,varName);
      // System.out.println(varName + " " + varType);
      if(varName.equals("Integer")){return "int";}
      if(varName.equals("Boolean")) {return "boolean";}
      
      //System.err.println("currentClass=" + ST.currentClass + ", currentMethod=" + ST.currentMethod + ", var=" + varName + ", varType=" + varType);
      if(varType==null){
         if(ST.classes.containsKey(varName)) return varName;
         System.out.println("Symbol not found");
         if(debug){
            System.err.println("Error:Identifier");
         }
         System.exit(0);
      }
      return varType;
   }

